/**
 * components/shared/Toast.js: ephemeral toast stack.
 *
 * Backs useToast(); transient feedback that confirms async results without
 * taking focus. Mount ToastProvider once near the root.
 *
 * @see CLAUDE.md (useToast / useConfirm), components/shared/Feedback.js
 */
import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';

const ToastCtx = createContext(null);

let counter = 0;
const nextId = () => ++counter;

/**
 * Provider rendering the toast stack; supplies the useToast() api.
 *
 *   const toast = useToast();
 *   toast.success('Invoice saved');
 *   toast.error({ title: 'Save failed', body: 'Network is down' });
 *
 * Auto-dismisses after 3500ms for success/info/warn; errors stay until the user
 * dismisses (they typically need reading + action). Up to 3 stacked (oldest
 * pushed off).
 *
 * @gotcha errors are inline by default; prefer Feedback for those. Toast is for
 *         the positive end (success) plus the occasional transient info.
 */
export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);
  const timers = useRef(new Map());

  const dismiss = useCallback((id) => {
    setToasts((t) => t.filter((x) => x.id !== id));
    const handle = timers.current.get(id);
    if (handle) { clearTimeout(handle); timers.current.delete(id); }
  }, []);

  const push = useCallback((tone, value) => {
    const v = typeof value === 'string' ? { title: value } : (value || {});
    const id = nextId();
    setToasts((t) => [...t.slice(-2), { id, tone, ...v }]);
    // Errors stay until dismissed; everything else auto-clears at 3.5s.
    if (tone !== 'error') {
      const handle = setTimeout(() => dismiss(id), 3500);
      timers.current.set(id, handle);
    }
    return id;
  }, [dismiss]);

  const api = {
    success: (v) => push('success', v),
    error:   (v) => push('error', v),
    warn:    (v) => push('warn', v),
    info:    (v) => push('info', v),
    dismiss,
  };

  useEffect(() => () => {
    timers.current.forEach((h) => clearTimeout(h));
    timers.current.clear();
  }, []);

  return (
    <ToastCtx.Provider value={api}>
      {children}
      <div className="toast-stack" aria-live="polite" aria-atomic="false">
        {toasts.map((t) => (
          <div key={t.id} className={`toast toast-${t.tone}`} role={t.tone === 'error' ? 'alert' : 'status'}>
            <div className="toast-title">{t.title}</div>
            {t.body ? <div className="toast-body">{t.body}</div> : null}
            <button type="button" className="toast-dismiss" onClick={() => dismiss(t.id)} aria-label="Dismiss">×</button>
          </div>
        ))}
      </div>
    </ToastCtx.Provider>
  );
}

/**
 * @returns {{success,error,warn,info,dismiss}} no-op stubs outside a provider.
 */
export function useToast() {
  const api = useContext(ToastCtx);
  if (!api) {
    if (process.env.NODE_ENV !== 'production') console.error('useToast called outside ToastProvider');
    return { success: () => {}, error: () => {}, warn: () => {}, info: () => {}, dismiss: () => {} };
  }
  return api;
}
