/**
 * components/auth/MFATOTPScreen.js: the AAL1 gate. Six digits or nothing.
 *
 * App.js renders this and ONLY this whenever `mfaState === 'needs_totp'`: a session that has
 * authenticated with a password and holds an enrolled factor it has not yet satisfied. There is
 * deliberately no skip and no route off this screen except signing out, which is what makes it
 * a gate rather than a prompt. Its sibling MFASetupScreen does allow a skip, because enrolling
 * and verifying are different questions.
 *
 * @security every RLS policy in this project ends in `AND public.is_aal2()`, so what this
 *           screen guards is not a screen, it is the entire data layer. A session that never
 *           clears it can read nothing but its own profile row.
 * @gotcha the attempt counter is LOCAL to this component and resets on reload, so it is a nudge
 *         toward a fresh code and not a lockout. The real brake is Supabase Auth's own rate
 *         limiting plus the password-stage lockout. Do not read MAX_TOTP_ATTEMPTS as a control.
 * @gotcha only a code the server REJECTED moves that counter. verifyTOTP makes three round
 *         trips and the first two never look at the code, so a 429 or a 502 counted as a wrong
 *         code and, five outages in, told someone holding a correct one to sign out and start
 *         over: advice to throw away a working session. @see utils/errors.js
 * @see hooks/useAuth.js (the mfaState machine), docs/CODEBASE.md
 */
import React, { useState, useRef, useEffect } from 'react';
import Feedback from '../shared/Feedback';
import { useAuth } from '../../hooks/useAuth';
import { humanizeError, isCredentialRejection } from '../../utils/errors';

/** Failures before the copy stops counting down and tells the user to start over. */
const MAX_TOTP_ATTEMPTS = 5;

export default function MFATOTPScreen() {
  const { verifyTOTP, signOut } = useAuth();
  const [code, setCode]         = useState('');
  const [error, setError]       = useState('');
  const [loading, setLoading]   = useState(false);
  const [attempts, setAttempts] = useState(0);
  const inputRef = useRef(null);

  useEffect(() => { inputRef.current?.focus(); }, []);

  async function handleSubmit(e) {
    e.preventDefault();
    if (code.length !== 6) { setError('Enter the 6-digit code from your authenticator app.'); return; }
    setLoading(true);
    setError('');
    const { error: err, stage } = await verifyTOTP(code);
    if (err && !(stage === 'verify' && isCredentialRejection(err))) {
      const h = humanizeError(err);
      setError(`${h?.title || 'The server is not answering'}. ${h?.body || 'Try again in a moment.'}`);
    } else if (err) {
      const next = attempts + 1;
      setAttempts(next);
      if (next >= MAX_TOTP_ATTEMPTS) {
        setError('Too many failed attempts. Please sign out and try again with a fresh code.');
      } else {
        setError(`Incorrect code. ${MAX_TOTP_ATTEMPTS - next} attempt${MAX_TOTP_ATTEMPTS - next !== 1 ? 's' : ''} remaining.`);
      }
      setCode('');
    }
    setLoading(false);
  }

  return (
    <div className="login-page">
      <div className="login-box">
        <a href="https://nysterys.com" style={{ textDecoration: 'none' }} target="_blank" rel="noopener noreferrer">
          <div className="login-logo">NYS<span>T</span>ERYS</div>
        </a>
        <div className="login-tagline">Two-Factor Auth</div>
        <div className="login-divider" />
        <p style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 20, lineHeight: 1.6 }}>
          Open your authenticator app and enter the 6-digit code shown for this account.
        </p>
        {error && <Feedback value={error} />}
        <form onSubmit={handleSubmit} autoComplete="one-time-code">
          <div className="form-group">
            <label className="form-label" htmlFor="totp-code">Authentication Code</label>
            <input
              id="totp-code"
              ref={inputRef}
              className="form-input"
              type="text"
              inputMode="numeric"
              pattern="[0-9]*"
              maxLength={6}
              value={code}
              onChange={e => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
              placeholder="000000"
              autoComplete="one-time-code"
              disabled={loading}
              style={{ letterSpacing: '0.3em', fontSize: 20, textAlign: 'center' }}
            />
          </div>
          <button
            className="btn btn-primary w-full mt-8"
            type="submit"
            disabled={loading || code.length !== 6 || attempts >= MAX_TOTP_ATTEMPTS}
            style={{ justifyContent: 'center' }}
          >
            {loading ? 'Verifying…' : 'Verify'}
          </button>
        </form>
        <button type="button" className="login-footer-link" onClick={signOut}>
          Sign out and use a different account
        </button>
      </div>
    </div>
  );
}
