/**
 * components/auth/MFASetupScreen.js: first-login enrollment, and the only MFA screen that can
 * offer a way out.
 *
 * Rendered when `mfaState === 'needs_enrollment'`: signed in, no authenticator factor. Unlike
 * MFATOTPScreen it can be SKIPPED, because someone enrolling for the first time may not have
 * their phone. The skip lives for one session.
 *
 * @security THE SKIP IS THE CALLER'S TO GRANT AND IS NOT GRANTED TO AN ADMIN. An AAL1 session
 *           still reads its own legal name, date of birth and home address, so App.js passes
 *           `onSkip` only for a creator and this screen renders no dismiss control without it.
 * @gotcha there is always SOME way off this screen. `useAuth` fails open to `needs_enrollment`
 *         when the AAL cannot be read, so a transient network failure renders it to someone
 *         already enrolled; without a skip the exit is Sign out.
 * @gotcha `onSkip` and `onComplete` set the same flag today but stay two props: a completed
 *         enrolment must not become interchangeable with a dismissed one.
 * @see hooks/useAuth.js (the mfaState machine)
 */
import React, { useState, useEffect, useRef } from 'react';
import Feedback from '../shared/Feedback';
import { useAuth } from '../../hooks/useAuth';
import { humanizeError, isCredentialRejection } from '../../utils/errors';

/**
 * The one way off this screen: the caller's skip when it granted one, and otherwise the
 * only exit that is safe to offer, which is ending the session.
 */
function Exit({ className, onSkip, signOut }) {
  return (
    <button type="button" className={className} onClick={onSkip || signOut}>
      {onSkip ? 'Skip for now' : 'Sign out'}
    </button>
  );
}

/**
 * The enrollment flow: fetch a factor, show its QR, take a code, confirm it.
 *
 * @param {{onSkip?:  => void, onComplete:  => void}} props both dismiss the screen.
 *        Omitting `onSkip` makes enrollment mandatory and swaps the three skip controls
 *        for a single Sign out.
 */
export default function MFASetupScreen({ onSkip, onComplete }) {
  const { enrollMFA, confirmEnrollment, signOut } = useAuth();
  const [step, setStep]             = useState('loading'); // loading | qr | verify | error
  const [factorId, setFactorId]     = useState(null);
  const [qrCode, setQrCode]         = useState('');
  const [secret, setSecret]         = useState('');
  const [showSecret, setShowSecret] = useState(false);
  const [code, setCode]             = useState('');
  const [error, setError]           = useState('');
  const [loading, setLoading]       = useState(false);
  const started = useRef(false);

  useEffect(() => {
    if (started.current) return;
    started.current = true;
    async function start() {
      const { factorId: fid, qrCode: qr, secret: sec, error: err } = await enrollMFA();
      if (err) {
        setError(onSkip
          ? 'Could not start setup. Try again or skip for now.'
          : 'Could not start setup. Try again, or sign out and come back.');
        setStep('error');
        return;
      }
      setFactorId(fid);
      setQrCode(qr);
      setSecret(sec);
      setStep('qr');
    }
    start();
  }, []);

  async function handleVerify(e) {
    e.preventDefault();
    if (code.length !== 6) { setError('Enter the 6-digit code from your app.'); return; }
    setLoading(true);
    setError('');
    const { error: err, stage } = await confirmEnrollment(factorId, code);
    if (err && !(stage === 'verify' && isCredentialRejection(err))) {
      // Not a wrong code: the challenge round trip never sees one. Saying so stops sending
      // people to fix a phone clock that is already right.
      const h = humanizeError(err);
      setError(`${h?.title || 'The server is not answering'}. ${h?.body || 'Try again in a moment.'}`);
    } else if (err) {
      setError('Incorrect code. Make sure your phone time is correct and try again.');
      setCode('');
    } else {
      onComplete?.();
    }
    setLoading(false);
  }

  return (
    <div className="login-page">
      <div className="login-box" style={{ maxWidth: 420 }}>
        <a href="https://nysterys.com" style={{ textDecoration: 'none' }}>
          <div className="login-logo">NYS<span>T</span>ERYS</div>
        </a>
        <div className="login-tagline">Set Up Two-Factor Auth</div>
        <div className="login-divider" />

        {step === 'loading' && (
          <div className="text-muted" style={{ textAlign: 'center', padding: '20px 0' }}>
            Generating setup code…
          </div>
        )}

        {step === 'error' && (
          <>
            <Feedback value={error} />
            <Exit className="btn btn-ghost w-full mt-8" onSkip={onSkip} signOut={signOut} />
          </>
        )}

        {step === 'qr' && (
          <>
            <p style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 20, lineHeight: 1.6 }}>
              Open your authenticator app (Google Authenticator, Authy, or 1Password), tap the{' '}
              <strong style={{ color: 'var(--white)' }}>+</strong> button, and scan this QR code.
            </p>
            <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 16 }}>
              <img
                src={qrCode}
                alt="QR code for authenticator setup"
                style={{ width: 180, height: 180, borderRadius: 8, background: 'var(--paper)', padding: 8 }}
              />
            </div>
            <button type="button" className="login-footer-link"
              onClick={() => setShowSecret(s => !s)}
              style={{ marginBottom: showSecret ? 8 : 20 }}>
              {showSecret ? 'Hide manual code' : "Can't scan? Enter the code manually instead"}
            </button>
            {showSecret && (
              <div style={{
                background: 'var(--surface2)', borderRadius: 6, padding: '10px 14px',
                fontFamily: 'monospace', fontSize: 12, letterSpacing: '0.12em',
                wordBreak: 'break-all', marginBottom: 20, color: 'var(--white)',
              }}>
                {secret}
              </div>
            )}
            <button className="btn btn-primary w-full" onClick={() => setStep('verify')}
              style={{ justifyContent: 'center' }}>
              I've scanned the code →
            </button>
            <Exit className="login-footer-link" onSkip={onSkip} signOut={signOut} />
          </>
        )}

        {step === 'verify' && (
          <>
            <p style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 20, lineHeight: 1.6 }}>
              Enter the 6-digit code your authenticator app is showing now to confirm everything is working.
            </p>
            {error && <Feedback value={error} />}
            <form onSubmit={handleVerify} autoComplete="one-time-code">
              <div className="form-group">
                <label className="form-label" htmlFor="mfa-setup-code">Verification Code</label>
                <input
                  id="mfa-setup-code"
                  className="form-input"
                  type="text"
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={6}
                  value={code}
                  onChange={e => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                  placeholder="000000"
                  autoFocus
                  autoComplete="one-time-code"
                  disabled={loading}
                  style={{ letterSpacing: '0.3em', fontSize: 20, textAlign: 'center' }}
                />
              </div>
              <button
                className="btn btn-primary w-full mt-8"
                type="submit"
                disabled={loading || code.length !== 6}
                style={{ justifyContent: 'center' }}
              >
                {loading ? 'Confirming…' : 'Confirm & Enable 2FA'}
              </button>
            </form>
            <button type="button" className="login-footer-link" onClick={() => { setStep('qr'); setError(''); }}>
              ← Back to QR code
            </button>
            <Exit className="login-footer-link" onSkip={onSkip} signOut={signOut} />
          </>
        )}
      </div>
    </div>
  );
}
