/**
 * components/shared/Feedback.js: the .feedback banner (persistent, inline).
 *
 * For inline form errors, success, and informational banners that should stay
 * put (not auto-dismiss). For ephemeral confirmations use Toast instead. Accepts
 * a string (legacy: treated as an error title) or a { tone, title, body } object
 * from humanizeError().
 *
 * `detail` is the server's own sentence, rendered closed. A reader never has to open it, and
 * when a rule turns out to have no plain-English arm yet, opening it is how the refusal gets
 * reported without a screenshot of the console. Native <details>, so it is keyboard operable
 * with no JavaScript and stays inside the banner's single role="alert".
 *
 * @gotcha the .feedback family uses a full thin border + leading-dot indicator;
 *         never a colored side-stripe (banned visual). @see CLAUDE.md
 * @see utils/errors.js humanizeError, components/shared/Toast.js
 */
import React from 'react';

export default function Feedback({ value, onDismiss, style, className }) {
  if (!value) return null;
  const v = typeof value === 'string' ? { tone: 'error', title: value } : value;
  const tone = v.tone || 'error';
  return (
    <div
      className={`feedback feedback-${tone}${className ? ` ${className}` : ''}`}
      role={tone === 'error' || tone === 'warn' ? 'alert' : 'status'}
      style={style}
    >
      <div className="feedback-title">{v.title}</div>
      {v.body ? <div className="feedback-body">{v.body}</div> : null}
      {v.detail ? (
        <details className="feedback-detail">
          <summary>technical detail</summary>
          <code>{v.detail}</code>
        </details>
      ) : null}
      {onDismiss ? (
        <button
          type="button"
          className="feedback-dismiss"
          onClick={onDismiss}
          aria-label="Dismiss"
        >
          ×
        </button>
      ) : null}
    </div>
  );
}
