/**
 * components/shared/ConfirmDialog.js: the promise-based confirm modal.
 *
 * Backs useConfirm; the app-wide replacement for window.confirm. Mount
 * ConfirmProvider once near the root.
 *
 * @see docs/DESIGN.md. Enforced by no-restricted-globals and no-restricted-properties
 *      in hub-src/eslint.ci.cjs; this file holds the one licensed exception.
 */
import React, { useCallback, useEffect, useRef, useState } from 'react';
import Modal from './Modal';
import { ConfirmCtx } from '../../contexts/ConfirmContext';

/**
 * Provider rendering the confirm modal; supplies the useConfirm resolver.
 *
 *   if (!(await confirm({ title: 'Delete invoice?', body: 'Cannot be undone.', danger: true }))) return;
 *
 * Options: `title` (required), `body`, `confirmLabel`, `cancelLabel`, `danger`;
 * `requireTyped` demands an exact string before Confirm enables, for high-stakes deletes; and
 * `verify` is an async (value) => true | string that runs on confirm, with `inputLabel`,
 * `inputMode` and `maxLength` shaping its field.
 *
 * @gotcha requireTyped is synchronous and `verify` is not, so ONLY `verify` may leave the dialog
 *         open after Confirm is pressed. Everything else about the two is the same input and the
 *         same button, which is why they share the machinery rather than growing a second modal.
 */
export function ConfirmProvider({ children }) {
  const [state, setState] = useState(null);
  const [typed, setTyped] = useState('');
  const [checking, setChecking] = useState(false);
  const [failure, setFailure] = useState('');
  const inputRef = useRef(null);
  const cancelRef = useRef(null);

  const close = useCallback((result) => {
    setState((s) => {
      if (s) s.resolve(result);
      return null;
    });
    setTyped('');
    setFailure('');
    setChecking(false);
  }, []);

  /**
   * The confirm button. With `verify` set this is async and may decline to close.
   *
   * @gotcha a failed verify clears the field and keeps focus, rather than closing and making
   *         the user find the button again. It does NOT count attempts: there is no lockout
   *         here and the copy must not imply one.
   */
  const attempt = useCallback(async () => {
    if (!state?.verify) { close(true); return; }
    setChecking(true);
    setFailure('');
    let result;
    try {
      result = await state.verify(typed);
    } catch {
      result = 'Something went wrong. Try again.';
    }
    setChecking(false);
    if (result === true) { close(true); return; }
    setFailure(typeof result === 'string' ? result : 'That did not match.');
    setTyped('');
    if (inputRef.current) inputRef.current.focus();
  }, [close, state, typed]);

  const confirm = useCallback(
    (opts) =>
      new Promise((resolve) => {
        setTyped('');
        setFailure('');
        setChecking(false);
        setState({ ...opts, resolve });
      }),
    []
  );

  // A dialog that asks for a value: the field is the affordance, so Enter in it is a
  // deliberate second act and cannot fire until the value is right.
  const asksForValue = !!(state?.requireTyped || state?.verify);

  useEffect(() => {
    if (!state) return undefined;
    // Escape belongs to Modal, which is the only thing that knows whether this dialog is
    // the topmost overlay.
    //
    // @gotcha Enter is bound ONLY for a dialog that asks for a value, and the default focus
    //         is CANCEL. Both halves are the same defect: a document-level Enter plus an
    //         autofocused Delete meant the key that dismissed the previous screen, or a
    //         second press of the one that opened this dialog, destroyed the record. The
    //         guard has to cost one deliberate act or it is not a guard. On a dialog that
    //         asks for a value neither applies: `canConfirm` is false until the field
    //         matches, so Enter there is the third keystroke of an answer.
    const onKey = (e) => {
      if (e.key === 'Enter' && asksForValue && canConfirm && !checking) attempt();
    };
    if (asksForValue) document.addEventListener('keydown', onKey);
    if (asksForValue && inputRef.current) inputRef.current.focus();
    else if (cancelRef.current) cancelRef.current.focus();
    return () => document.removeEventListener('keydown', onKey);
  });

  const canConfirm = state?.verify
    ? typed.length >= (state.minLength ?? 1) && !checking
    : !state?.requireTyped || typed === state.requireTyped;

  return (
    <ConfirmCtx.Provider value={confirm}>
      {children}
      {state ? (
        <Modal title={state.title} size="sm" onClose={() => close(false)} showClose={false} guard={false}>
            <div className="modal-body">
              {state.body ? (
                <div style={{ color: 'var(--muted)', fontSize: 13, lineHeight: 1.5 }}>{state.body}</div>
              ) : null}
              {state.verify ? (
                <div style={{ marginTop: 16 }}>
                  <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 6 }}>
                    {state.inputLabel || 'Confirm'}
                  </div>
                  <input aria-label={state.inputLabel || 'Confirm'}
                    ref={inputRef}
                    className="form-input"
                    type="text"
                    value={typed}
                    onChange={(e) => setTyped(e.target.value)}
                    inputMode={state.inputMode || 'text'}
                    maxLength={state.maxLength}
                    autoComplete="one-time-code"
                    spellCheck={false}
                  />
                  {failure ? (
                    <div style={{ color: 'var(--red)', fontSize: 12, marginTop: 8 }}>{failure}</div>
                  ) : null}
                </div>
              ) : null}
              {state.requireTyped ? (
                <div style={{ marginTop: 16 }}>
                  <div style={{ color: 'var(--muted)', fontSize: 12, marginBottom: 6 }}>
                    Type <code style={{ color: 'var(--white)', letterSpacing: '0.5px' }}>{state.requireTyped}</code> to confirm.
                  </div>
                  <input aria-label={`Type ${state.requireTyped} to confirm`}
                    ref={inputRef}
                    className="form-input"
                    type="text"
                    value={typed}
                    onChange={(e) => setTyped(e.target.value)}
                    autoComplete="off"
                    spellCheck={false}
                  />
                </div>
              ) : null}
            </div>
            <div className="modal-footer">
              <button type="button" ref={cancelRef} className="btn btn-ghost btn-sm" onClick={() => close(false)}>
                {state.cancelLabel || 'Cancel'}
              </button>
              <button
                type="button"
                className={`btn btn-sm ${state.danger ? 'btn-danger' : 'btn-primary'}`}
                onClick={attempt}
                disabled={!canConfirm}
              >
                {checking ? 'Checking…' : (state.confirmLabel || (state.danger ? 'Delete' : 'Confirm'))}
              </button>
            </div>
        </Modal>
      ) : null}
    </ConfirmCtx.Provider>
  );
}

// Re-exported so nothing outside components/shared/ has to know the context moved. Inside
// components/shared/, import it from the context module: this line is the cycle.
export { useConfirm } from '../../contexts/ConfirmContext';
