/**
 * hooks/useAuth.js - auth and MFA session state for the whole hub.
 *
 * Owns the Supabase session, the user's profile, and the TOTP assurance machine. App.js reads
 * mfaState to gate what renders; everything downstream reads `profile`/`isAdmin`/`isCreator`.
 *
 * mfaState: null (signed out) | 'needs_totp' | 'needs_enrollment' | 'ready'.
 *   - needs_totp: a factor exists but the session is still AAL1, so the user must pass TOTP.
 *     The profile is NOT fetched, so an AAL1 session never holds profile data.
 *   - needs_enrollment: no factor enrolled. Grace period: profile fetched, access granted with
 *     a skippable enrollment prompt.
 *   - ready: AAL2 reached, profile fetched, full access.
 *
 * @security data access is gated on AAL2 by RLS (public.is_aal2); this hook mirrors that in the
 *           UI but is NOT the enforcement point. A user who bypassed these screens still hits
 *           AAL1 RLS denial server-side.
 * @see docs/CODEBASE.md (auth / MFA flow)
 */
import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { supabase, isHandlingPasswordReset } from '../lib/supabase';
import { clearStepUpWindow } from '../utils/stepUpWindow';

const AuthContext = createContext({});

/**
 * Provider that resolves the session, runs the MFA assurance check, and exposes
 * the auth API (signIn/signOut + the MFA enroll/verify helpers) via context.
 */
export function AuthProvider({ children }) {
  const [user, setUser]         = useState(null);
  const [profile, setProfile]   = useState(null);
  const [loading, setLoading]   = useState(true);
  // null | 'needs_totp' | 'needs_enrollment' | 'ready'
  const [mfaState, setMfaState] = useState(null);

  /**
   * Load the signed-in user's shell profile: the seven columns the app chrome
   * needs, and none of the sensitive ones.
   *
   * @security goes through get_my_shell_profile rather than reading profiles
   *           directly, because the SELECT policy on that table now requires a
   *           second factor (: it was
   *           the only policy in the schema that did not, over legal name, date
   *           of birth and home address). One of the two callers below is the
   *           needs_enrollment branch, which runs at AAL1 by definition, so a
   *           direct select there would return nothing and sign the user out at
   *           first sight of their own account.
   * @gotcha on any fetch failure this signs the user OUT (a session with no
   *         readable profile is treated as invalid, not as a partial login).
   *         Only ever called once mfaState has cleared to ready/needs_enrollment.
   */
  const fetchProfile = useCallback(async () => {
    const { data: rows, error } = await supabase.rpc('get_my_shell_profile');
    const data = Array.isArray(rows) ? rows[0] : rows;

    if (error || !data) {
      if (process.env.NODE_ENV !== 'production') console.warn('Profile fetch failed, signing out:', error?.message);
      await supabase.auth.signOut();
      setUser(null);
      setProfile(null);
    } else {
      setProfile(data);
    }
    setLoading(false);
  }, []);

  /**
   * Resolve the session's AAL and set mfaState accordingly (see the machine in
   * the file header). Fetches the profile only on the ready / needs_enrollment
   * branches; the needs_totp branch deliberately leaves profile null at AAL1.
   * @gotcha if AAL cannot be determined, fail OPEN to needs_enrollment (grace
   *         period) rather than locking the user out of a transient API error.
   *         Server-side RLS still enforces AAL2, so this is safe.
   */
  const checkMfaLevel = useCallback(async (userId) => {
    const { data, error } = await supabase.auth.mfa.getAuthenticatorAssuranceLevel();
    if (error || !data) {
      // Can't determine AAL - treat as unenrolled, still grant access (grace period)
      setMfaState('needs_enrollment');
      await fetchProfile();
      return;
    }
    const { currentLevel, nextLevel } = data;
    if (currentLevel === 'aal2') {
      setMfaState('ready');
      await fetchProfile();
    } else if (nextLevel === 'aal2') {
      // Enrolled but not verified this session - must complete TOTP before data access
      setMfaState('needs_totp');
      setLoading(false);
    } else {
      // Not enrolled - grace period: fetch profile and allow access with warning
      setMfaState('needs_enrollment');
      await fetchProfile();
    }
  }, [fetchProfile]);

  // Resolve the initial session, then keep mfaState/user/profile in sync with
  // every auth event. PASSWORD_RECOVERY and the LoginPage recovery flow are
  // ignored here so a mid-reset SIGNED_IN does not bounce the user to a
  // dashboard (see isHandlingPasswordReset in lib/supabase.js).
  useEffect(() => {
    let mounted = true;

    supabase.auth.getSession().then(({ data: { session } }) => {
      if (!mounted) return;
      setUser(session?.user ?? null);
      if (session?.user) checkMfaLevel(session.user.id);
      else setLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        if (!mounted) return;

        if (isHandlingPasswordReset) {
          setLoading(false);
          return;
        }

        if (event === 'PASSWORD_RECOVERY') {
          setLoading(false);
          return;
        }

        setUser(session?.user ?? null);
        if (session?.user) {
          checkMfaLevel(session.user.id);
        } else {
          setProfile(null);
          setMfaState(null);
          setLoading(false);
        }
      }
    );

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, [checkMfaLevel]);

  async function signIn(email, password) {
    const { error } = await supabase.auth.signInWithPassword({
      email: email.trim().toLowerCase(),
      password,
    });
    return { error };
  }

  async function signOut() {
    setProfile(null);
    setUser(null);
    setMfaState(null);
    // Without this, signing out and back in on a shared machine
    // inside the window would inherit the previous person's step-up unlock.
    clearStepUpWindow();
    await supabase.auth.signOut();
  }

  /**
   * Verify a TOTP code against the user's enrolled factor to lift the session
   * to AAL2, then flip mfaState to ready and fetch the profile.
   *
   * @returns {Promise<{error: object|null, stage: 'list'|'challenge'|'verify'|null}>} `stage`
   *          says WHICH of the three round trips failed. Without it the caller has one
   *          `{ error }` covering a refused factor READ, a refused challenge and a rejected
   *          code, and it called all three "Incorrect code", burning an attempt against a
   *          correct one.
   */
  async function verifyTOTP(code) {
    const { data: factors, error: lErr } = await supabase.auth.mfa.listFactors();
    if (lErr) return { error: lErr, stage: 'list' };
    const totp = factors?.totp?.[0];
    if (!totp) return { error: { code: 'no_factor', message: 'No authenticator app found.' }, stage: 'list' };

    const { data: challenge, error: cErr } = await supabase.auth.mfa.challenge({ factorId: totp.id });
    if (cErr) return { error: cErr, stage: 'challenge' };

    const { error: vErr } = await supabase.auth.mfa.verify({
      factorId: totp.id,
      challengeId: challenge.id,
      code,
    });
    if (vErr) return { error: vErr, stage: 'verify' };

    setMfaState('ready');
    await fetchProfile();
    return { error: null, stage: null };
  }

  /**
   * Begin TOTP enrollment.
   * @returns {Promise<{factorId, qrCode, secret, error}>} the QR + secret to show
   *          the user; pass factorId back to confirmEnrollment with their code.
   */
  async function enrollMFA() {
    const { data, error } = await supabase.auth.mfa.enroll({ factorType: 'totp' });
    if (error) return { error };
    return {
      factorId: data.id,
      qrCode: data.totp.qr_code,
      secret: data.totp.secret,
      error: null,
    };
  }

  /**
   * Confirm a freshly enrolled factor with the user's code; sets mfaState ready.
   * @returns {Promise<{error: object|null, stage: 'challenge'|'verify'|null}>} same reason as
   *          verifyTOTP: the challenge never looks at the code, so its failure is not a wrong
   *          one, and the screen told people to check their phone's clock over a 502.
   */
  async function confirmEnrollment(factorId, code) {
    const { data: challenge, error: cErr } = await supabase.auth.mfa.challenge({ factorId });
    if (cErr) return { error: cErr, stage: 'challenge' };

    const { error: vErr } = await supabase.auth.mfa.verify({
      factorId,
      challengeId: challenge.id,
      code,
    });
    if (vErr) return { error: vErr, stage: 'verify' };

    setMfaState('ready');
    return { error: null, stage: null };
  }

  /** Remove an enrolled factor; drops mfaState back to needs_enrollment. */
  async function unenrollMFA(factorId) {
    const { error } = await supabase.auth.mfa.unenroll({ factorId });
    if (error) return { error };
    setMfaState('needs_enrollment');
    return { error: null };
  }

  /** @returns {Promise<{factors: object[], error}>} the user's TOTP factors ([] when none). */
  async function listMFAFactors() {
    const { data, error } = await supabase.auth.mfa.listFactors();
    if (error) return { factors: null, error };
    return { factors: data?.totp ?? [], error: null };
  }

  return (
    <AuthContext.Provider value={{
      user, profile, loading, mfaState,
      signIn, signOut, fetchProfile,
      verifyTOTP, enrollMFA, confirmEnrollment, unenrollMFA, listMFAFactors,
      isAdmin: profile?.role === 'admin',
      isCreator: profile?.role === 'creator',
    }}>
      {children}
    </AuthContext.Provider>
  );
}

/** Access the auth context: { user, profile, loading, mfaState, isAdmin, isCreator...api }. */
export function useAuth() {
  return useContext(AuthContext);
}
