/**
 * hooks/useUnsavedGuard.js: one answer to "is there typed work on screen that would be lost?"
 *
 * Dirtiness is OBSERVED rather than declared. A container spreads `dirtyProps` and any change
 * inside it marks it dirty, so a form nobody wired is still guarded; asking forty call sites
 * to track a flag is how thirty nine of them end up not tracking one.
 *
 * Three consumers, three routes out. `components/shared/Modal.js` guards its own X, Escape and
 * `ModalClose`. A detail panel guards nothing itself, because it has no close button of its
 * own: it is dismissed by navigating, so `hasUnsaved()` is what the shell asks before it
 * switches view. `beforeunload` covers reload, back and closing the tab, and is registered
 * only while something is dirty so an untouched screen never triggers the native prompt.
 *
 * @invariant `hasUnsaved()` is true if and only if at least one mounted container has seen a
 *            change and has not been unmounted. Unmounting IS the deregistration, which is
 *            correct: every form in this hub disappears when it saves.
 * @see components/shared/Modal.js
 */
import { useCallback, useEffect, useRef, useState } from 'react';

/** Mounted containers that have seen a change. Module scope: the shell asks across the tree. */
const dirtyKeys = new Set();
let nextKey = 0;

/** Is there typed and unsaved work anywhere on screen right now? */
export function hasUnsaved() {
  return dirtyKeys.size > 0;
}

/** The copy every route out uses, so one screen never meets two words for one thing. */
export const DISCARD_PROMPT = {
  title: 'Discard your changes?',
  body: 'What you have typed here has not been saved, and leaving loses it.',
  confirmLabel: 'Discard',
  cancelLabel: 'Keep editing',
  danger: true,
};

/**
 * @param {boolean} [enabled=true] false opts a container out, for a dialog whose typed input
 *        IS the confirmation and which would otherwise ask about itself.
 * @returns {{dirty: boolean, dirtyProps: object, reset: () => void}} spread `dirtyProps` on
 *          the container element.
 */
export function useUnsavedGuard(enabled = true) {
  const keyRef = useRef(null);
  if (keyRef.current === null) { nextKey += 1; keyRef.current = `u${nextKey}`; }
  const [dirty, setDirty] = useState(false);
  const dirtyRef = useRef(false);

  const mark = useCallback(() => {
    if (dirtyRef.current || !enabled) return;
    dirtyRef.current = true;
    dirtyKeys.add(keyRef.current);
    setDirty(true);
  }, [enabled]);

  const reset = useCallback(() => {
    dirtyRef.current = false;
    dirtyKeys.delete(keyRef.current);
    setDirty(false);
  }, []);

  // Unmounting is how a form leaves, whether it saved or was discarded, so the cleanup is the
  // only deregistration there needs to be.
  useEffect(() => () => { dirtyKeys.delete(keyRef.current); }, []);

  useEffect(() => {
    if (!enabled || !dirty) return undefined;
    const onBeforeUnload = (e) => { e.preventDefault(); e.returnValue = ''; };
    window.addEventListener('beforeunload', onBeforeUnload);
    return () => window.removeEventListener('beforeunload', onBeforeUnload);
  }, [enabled, dirty]);

  return {
    dirty,
    reset,
    dirtyProps: { onChangeCapture: mark, onInputCapture: mark },
  };
}
