/**
 * hooks/useIdleTimeout.js - auto sign-out after a per-user idle window, with a 60s warning the
 * user can cancel. Used by App.js (AppInner) to drive the IdleWarning modal.
 *
 * The window is profile.idle_timeout_minutes. NULL and 0 are different: null means nobody has
 * configured this account and gets DEFAULT_IDLE_MINUTES, 0 means an admin turned it off for
 * this person and stays off. Activity (mouse/key/touch/scroll) resets it, throttled so a moving
 * mouse does not reschedule on every event.
 *
 * @security the column has no DEFAULT and no NOT NULL, and handle_new_user() does not insert
 *           it, so every account starts null. Reading null as "disabled" turns the idle timeout
 *           off for everybody until an admin sets it one person at a time. Separating the two
 *           absent values is the whole point.
 * @gotcha signOut from AuthProvider changes identity every render. Using it as a hook dep would
 *         make scheduleIdle to resetTimer to the effect re-run on every render and continuously
 *         reset the timer before it ever fires. It is held in a ref instead.
 */
import { useEffect, useRef, useState, useCallback } from 'react';

const WARNING_SECONDS = 60;
const THROTTLE_MS = 2000;

/**
 * The window an account gets when nobody has chosen one. Long enough not to interrupt a working
 * session, short enough that an unattended screen in a shared house does not stay signed in all
 * day, which is the threat this control is actually about.
 */
export const DEFAULT_IDLE_MINUTES = 30;

/**
 * The longest idle window an admin may configure, eight hours.
 *
 * @gotcha `profiles.idle_timeout_minutes` carries no CHECK, and `max` on a number input only
 *         advises, so this constant is the only bound there is. Anything that writes the
 *         column must range-check against it.
 */
export const IDLE_MINUTES_MAX = 480;

/**
 * @param {{profile: object, signOut: () => void}} args
 * @returns {{showWarning: boolean, countdown: number, stayLoggedIn: () => void, secondsLeft: number|null}}
 *          secondsLeft is the live time-to-idle for an ambient display; countdown
 *          is the 60s warning ticker.
 */
export function useIdleTimeout({ profile, signOut }) {
  const [showWarning, setShowWarning] = useState(false);
  const [countdown, setCountdown]     = useState(WARNING_SECONDS);
  const [secondsLeft, setSecondsLeft] = useState(null);

  // Held in a ref to keep the callbacks stable (see the file header @gotcha).
  const signOutRef           = useRef(signOut);
  signOutRef.current         = signOut;

  // null/undefined -> the default. An explicit 0 -> off. Anything else -> as given. `profile`
  // itself being absent means there is no session to time out.
  const configured = profile ? profile.idle_timeout_minutes : 0;
  const minutes = configured == null ? DEFAULT_IDLE_MINUTES : configured;
  const timeoutMs = minutes > 0 ? minutes * 60 * 1000 : null;

  const timeoutMsRef         = useRef(timeoutMs);
  timeoutMsRef.current       = timeoutMs;

  const idleTimerRef         = useRef(null);
  const countdownIntervalRef = useRef(null);
  const tickIntervalRef      = useRef(null);
  const showingWarningRef    = useRef(false);
  const lastActivityRef      = useRef(Date.now());
  const deadlineRef          = useRef(null);

  // [] deps - stable forever; calls signOut via ref so no dep needed
  const startCountdown = useCallback(() => {
    showingWarningRef.current = true;
    setShowWarning(true);
    clearInterval(tickIntervalRef.current);
    setSecondsLeft(null);
    let secs = WARNING_SECONDS;
    setCountdown(secs);
    clearInterval(countdownIntervalRef.current);
    countdownIntervalRef.current = setInterval(() => {
      secs -= 1;
      setCountdown(secs);
      if (secs <= 0) {
        clearInterval(countdownIntervalRef.current);
        setShowWarning(false);
        signOutRef.current();
      }
    }, 1000);
  }, []);

  // Stable because startCountdown is stable
  const scheduleIdle = useCallback(() => {
    const ms = timeoutMsRef.current;
    if (!ms) return;
    clearTimeout(idleTimerRef.current);
    clearInterval(tickIntervalRef.current);
    const warningDelay = Math.max(0, ms - WARNING_SECONDS * 1000);
    deadlineRef.current = Date.now() + ms;
    setSecondsLeft(Math.ceil(ms / 1000));
    idleTimerRef.current = setTimeout(startCountdown, warningDelay);
    tickIntervalRef.current = setInterval(() => {
      const secs = Math.max(0, Math.ceil((deadlineRef.current - Date.now()) / 1000));
      setSecondsLeft(secs);
    }, 1000);
  }, [startCountdown]);

  // Stable because scheduleIdle is stable
  const resetTimer = useCallback(() => {
    if (!timeoutMsRef.current) return;
    const now = Date.now();
    if (showingWarningRef.current) {
      showingWarningRef.current = false;
      setShowWarning(false);
      setCountdown(WARNING_SECONDS);
      clearInterval(countdownIntervalRef.current);
    } else {
      if (now - lastActivityRef.current < THROTTLE_MS) return;
    }
    lastActivityRef.current = now;
    scheduleIdle();
  }, [scheduleIdle]);

  useEffect(() => {
    if (!timeoutMs) return;
    const events = ['mousemove', 'keydown', 'mousedown', 'touchstart', 'scroll', 'click'];
    events.forEach(e => window.addEventListener(e, resetTimer, { passive: true }));
    scheduleIdle();
    return () => {
      events.forEach(e => window.removeEventListener(e, resetTimer));
      clearTimeout(idleTimerRef.current);
      clearInterval(countdownIntervalRef.current);
      clearInterval(tickIntervalRef.current);
    };
  }, [timeoutMs, resetTimer, scheduleIdle]);

  const stayLoggedIn = useCallback(() => resetTimer(), [resetTimer]);

  return { showWarning, countdown, stayLoggedIn, secondsLeft };
}
