/**
 * pages/LoginPage.js - unauthenticated entry screen.
 *
 * Three modes: 'login' (email + password), 'reset' (request reset email),
 * 'set-password' (set a new password after following a recovery link). MFA is
 * handled downstream by useAuth, not here.
 *
 * @security Client-side lockout: 5 failed attempts then 15 min, persisted in
 *           localStorage. This is a UX speed bump only; Supabase server-side
 *           rate limiting is the real control, so a cleared localStorage does
 *           not defeat anything. @see docs/CODEBASE.md (auth)
 * @gotcha only a REJECTED credential may move that counter. A 429, a 502 or an unreachable
 *         auth service is not a wrong password, and counting it spent an attempt, persisted
 *         it, and after five outages locked a correct password out for fifteen minutes.
 *         @see utils/errors.js isCredentialRejection
 */
import React, { useState, useEffect } from 'react';
import { useAuth } from '../hooks/useAuth';
import { supabase, setHandlingPasswordReset } from '../lib/supabase';
import { humanizeError, isCredentialRejection } from '../utils/errors';

const EyeIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
    <circle cx="12" cy="12" r="3"/>
  </svg>
);
const EyeOffIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <path d="M17.94 17.94A10.07 10.07 0 0112 20c-7 0-11-8-11-8a18.45 18.45 0 015.06-5.94M9.9 4.24A9.12 9.12 0 0112 4c7 0 11 8 11 8a18.5 18.5 0 01-2.16 3.19m-6.72-1.07a3 3 0 11-4.24-4.24"/>
    <line x1="1" y1="1" x2="23" y2="23"/>
  </svg>
);

const MAX_ATTEMPTS = 5;
const LOCKOUT_MS   = 15 * 60 * 1000;
const STORAGE_KEY  = 'nys_auth_lockout';

function readLockout() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { attempts: 0, lockoutUntil: null };
    const { attempts, lockoutUntil } = JSON.parse(raw);
    return { attempts: attempts ?? 0, lockoutUntil: lockoutUntil ?? null };
  } catch {
    return { attempts: 0, lockoutUntil: null };
  }
}

function writeLockout(attempts, lockoutUntil) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ attempts, lockoutUntil }));
  } catch { /* storage unavailable: Supabase server-side rate limiting still applies */ }
}

function clearLockout() {
  try { localStorage.removeItem(STORAGE_KEY); } catch {}
}

/** The login / reset / set-password screen (mode state drives which form renders). */
export default function LoginPage() {
  const { signIn } = useAuth();

  const [mode, setMode]                       = useState('login');
  const [email, setEmail]                     = useState('');
  const [password, setPassword]               = useState('');
  const [newPassword, setNewPassword]         = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError]                     = useState('');
  const [success, setSuccess]                 = useState('');
  const [loading, setLoading]                 = useState(false);
  const [attempts, setAttempts]               = useState(0);
  const [lockoutUntil, setLockoutUntil]       = useState(null);
  const [secondsLeft, setSecondsLeft]         = useState(0);
  const [showPassword,        setShowPassword]        = useState(false);
  const [showNewPassword,     setShowNewPassword]      = useState(false);
  const [showConfirmPassword, setShowConfirmPassword]  = useState(false);

  // Hydrate lockout state from localStorage on mount
  useEffect(() => {
    const stored = readLockout();
    const now = Date.now();
    if (stored.lockoutUntil && now < stored.lockoutUntil) {
      setAttempts(stored.attempts);
      setLockoutUntil(stored.lockoutUntil);
    } else if (stored.lockoutUntil) {
      // Lockout expired while browser was closed - clear it
      clearLockout();
    } else {
      setAttempts(stored.attempts);
    }
  }, []);

  // Live countdown - ticks every second while locked out
  useEffect(() => {
    if (!lockoutUntil) return;
    const tick = () => {
      const ms = lockoutUntil - Date.now();
      if (ms <= 0) {
        setLockoutUntil(null);
        setAttempts(0);
        clearLockout();
        setError('');
      } else {
        setSecondsLeft(Math.ceil(ms / 1000));
      }
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [lockoutUntil]);

  /**
   * Redeem the password-reset link.
   *
   * @security THE LINK CARRIES NO SESSION. Under PKCE it carries a one-time
   *           authorization code, and exchangeCodeForSession trades it for tokens using a
   *           verifier this browser generated when it asked for the reset and kept in its own
   *           storage. Opening the link in a different browser fails, which is the whole
   *           point: anyone holding the email must not be able to redeem it.
   *           @see lib/supabase.js
   * @gotcha the code is in the QUERY STRING, not the fragment, so it reaches the server in
   *         request logs and referrers if it survives a navigation. replaceState runs FIRST,
   *         before the exchange, for that reason.
   * @gotcha reset links minted under the old implicit flow arrive with tokens in the fragment
   *         and are deliberately NOT honoured. Accepting both would leave the bearer-credential
   *         path open for as long as one unexpired email exists. They expire within the hour;
   *         a user holding one sees the invalid-link message and requests another.
   */
  useEffect(() => {
    const code = new URLSearchParams(window.location.search).get('code');
    if (!code) return;

    setHandlingPasswordReset(true);
    window.history.replaceState(null, '', window.location.pathname);
    supabase.auth.exchangeCodeForSession(code)
      .then(({ error: sessionError }) => {
        if (sessionError) {
          setHandlingPasswordReset(false);
          setError('Reset link is invalid, expired, or was opened in a different browser than the one that requested it. Request a new one.');
          setMode('reset');
        } else {
          setMode('set-password');
        }
      });
  }, []);

  const lockedOut = !!(lockoutUntil && Date.now() < lockoutUntil);

  function formatCountdown(secs) {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = (secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  }

  async function handleLogin(e) {
    e.preventDefault();
    if (lockedOut) {
      setError(`Too many failed attempts. Try again in ${Math.ceil(secondsLeft / 60)} minute(s).`);
      return;
    }

    setLoading(true);
    setError('');
    const { error: signInError } = await signIn(email, password);

    if (signInError && !isCredentialRejection(signInError)) {
      // The server never checked the password, so nothing was learned about it: name the
      // failure and leave the counter exactly where it was.
      const h = humanizeError(signInError);
      setError(`${h?.title || 'The server is not answering'}. ${h?.body || 'Try again in a moment.'}`);
    } else if (signInError) {
      const next = attempts + 1;
      if (next >= MAX_ATTEMPTS) {
        const until = Date.now() + LOCKOUT_MS;
        setAttempts(next);
        setLockoutUntil(until);
        writeLockout(next, until);
        setError('Too many failed attempts. Account locked for 15 minutes.');
      } else {
        setAttempts(next);
        writeLockout(next, null);
        setError(`Invalid credentials. ${MAX_ATTEMPTS - next} attempt(s) remaining.`);
      }
    } else {
      clearLockout();
      setAttempts(0);
      setLockoutUntil(null);
    }
    setLoading(false);
  }

  async function handleRequestReset(e) {
    e.preventDefault();
    if (!email.trim()) { setError('Enter your email address.'); return; }
    setLoading(true);
    setError('');
    setSuccess('');
    const { error: resetError } = await supabase.auth.resetPasswordForEmail(email.trim().toLowerCase(), {
      redirectTo: `${window.location.origin}/hub/`,
    });
    // Only a successful send earns the success line. Discarding the result showed it whether
    // or not the mail was sent, so someone waiting on a link that was never queued has no
    // reason to try again. The copy stays non-committal about whether the address is
    // registered: that is deliberate, and unaffected here, because an unknown address does
    // not error.
    if (resetError) {
      const h = humanizeError(resetError);
      setError(`${h?.title || "Couldn't send the reset email"}. ${h?.body || 'Try again in a moment.'}`);
    } else {
      setSuccess("If that email is registered you'll receive a reset link shortly.");
    }
    setLoading(false);
  }

  async function handleSetPassword(e) {
    e.preventDefault();
    if (newPassword !== confirmPassword) { setError('Passwords do not match.'); return; }
    if (newPassword.length < 12) { setError('Password must be at least 12 characters.'); return; }
    const charRules = [
      { label: 'uppercase letter', test: /[A-Z]/ },
      { label: 'lowercase letter', test: /[a-z]/ },
      { label: 'number',           test: /[0-9]/ },
      { label: 'special character', test: /[^A-Za-z0-9]/ },
    ];
    const failing = charRules.filter(r => !r.test.test(newPassword));
    if (failing.length) {
      setError(`Password must include a ${failing.map(r => r.label).join(', a ')}.`);
      return;
    }
    setLoading(true);
    setError('');
    const { error: updateError } = await supabase.auth.updateUser({ password: newPassword });
    if (updateError) {
      setError('Could not update password. Your reset link may have expired: request a new one.');
    } else {
      setHandlingPasswordReset(false);
      await supabase.auth.signOut();
      setSuccess('Password set. Sign in with your new password.');
      setMode('login');
      setNewPassword('');
      setConfirmPassword('');
    }
    setLoading(false);
  }

  const taglines = {
    'login':        'Team Portal',
    'reset':        'Password Reset',
    'set-password': 'Set New Password',
  };

  return (
    <div className="login-page">
      <div className="login-box">
        <a href="https://nysterys.com" style={{ textDecoration: 'none' }} target="_blank" rel="noopener noreferrer">
          <div className="login-logo">NYS<span>T</span>ERYS</div>
        </a>
        <h1 className="login-tagline">{taglines[mode] || 'Team Portal'}</h1>
        <div className="login-divider" />

        {lockedOut && (
          <div className="login-error" role="alert">
            Account locked: try again in {formatCountdown(secondsLeft)}
          </div>
        )}
        {!lockedOut && error   && <div className="login-error" role="alert">{error}</div>}
        {!lockedOut && success && <div className="login-success" role="status" aria-live="polite">{success}</div>}

        {mode === 'login' && (
          <form onSubmit={handleLogin} autoComplete="on">
            <div className="form-group">
              <label className="form-label" htmlFor="email">Email</label>
              <input id="email" className="form-input" type="email" value={email}
                onChange={e => setEmail(e.target.value)} placeholder="you@nysterys.com"
                required autoFocus autoComplete="email" disabled={loading || lockedOut} />
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="password">Password</label>
              <div style={{ position: 'relative' }}>
                <input
                  id="password"
                  className="form-input"
                  type={showPassword ? 'text' : 'password'}
                  style={{ paddingRight: 40 }}
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="Your password"
                  required
                  autoComplete="current-password"
                  disabled={loading || lockedOut}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(v => !v)}
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                  style={{
                    position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)',
                    background: 'none', border: 'none', cursor: 'pointer',
                    color: 'var(--muted)', padding: 4, display: 'flex', alignItems: 'center',
                  }}
                >
                  {showPassword ? <EyeOffIcon /> : <EyeIcon />}
                </button>
              </div>
            </div>
            <button className="btn btn-primary w-full mt-8" type="submit"
              disabled={loading || lockedOut} style={{ justifyContent: 'center' }}>
              {loading ? 'Signing in…' : 'Sign In'}
            </button>
            <button type="button" className="login-footer-link"
              onClick={() => { setMode('reset'); setError(''); setSuccess(''); }}>
              Forgot password?
            </button>
          </form>
        )}

        {mode === 'reset' && (
          <form onSubmit={handleRequestReset} autoComplete="on">
            <div className="form-group">
              <label className="form-label" htmlFor="reset-email">Email</label>
              <input id="reset-email" className="form-input" type="email" value={email}
                onChange={e => setEmail(e.target.value)} placeholder="you@nysterys.com"
                required autoFocus autoComplete="email" disabled={loading} />
            </div>
            <button className="btn btn-primary w-full mt-8" type="submit"
              disabled={loading} style={{ justifyContent: 'center' }}>
              {loading ? 'Sending…' : 'Send Reset Link'}
            </button>
            <button type="button" className="login-footer-link"
              onClick={() => { setMode('login'); setError(''); setSuccess(''); }}>
              ← Back to sign in
            </button>
          </form>
        )}

        {mode === 'set-password' && (
          <form onSubmit={handleSetPassword} autoComplete="new-password">
            <div className="form-group">
              <label className="form-label" htmlFor="new-password">New Password</label>
              <div style={{ position: 'relative' }}>
                <input
                  id="new-password"
                  className="form-input"
                  type={showNewPassword ? 'text' : 'password'}
                  style={{ paddingRight: 40 }}
                  value={newPassword}
                  onChange={e => setNewPassword(e.target.value)}
                  placeholder="12+ characters"
                  required
                  autoFocus
                  autoComplete="new-password"
                  disabled={loading}
                />
                <button
                  type="button"
                  onClick={() => setShowNewPassword(v => !v)}
                  aria-label={showNewPassword ? 'Hide password' : 'Show password'}
                  style={{
                    position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)',
                    background: 'none', border: 'none', cursor: 'pointer',
                    color: 'var(--muted)', padding: 4, display: 'flex', alignItems: 'center',
                  }}
                >
                  {showNewPassword ? <EyeOffIcon /> : <EyeIcon />}
                </button>
              </div>
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="confirm-password">Confirm Password</label>
              <div style={{ position: 'relative' }}>
                <input
                  id="confirm-password"
                  className="form-input"
                  type={showConfirmPassword ? 'text' : 'password'}
                  style={{ paddingRight: 40 }}
                  value={confirmPassword}
                  onChange={e => setConfirmPassword(e.target.value)}
                  placeholder="Same password again"
                  required
                  autoComplete="new-password"
                  disabled={loading}
                />
                <button
                  type="button"
                  onClick={() => setShowConfirmPassword(v => !v)}
                  aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                  style={{
                    position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)',
                    background: 'none', border: 'none', cursor: 'pointer',
                    color: 'var(--muted)', padding: 4, display: 'flex', alignItems: 'center',
                  }}
                >
                  {showConfirmPassword ? <EyeOffIcon /> : <EyeIcon />}
                </button>
              </div>
            </div>
            <button className="btn btn-primary w-full mt-8" type="submit"
              disabled={loading} style={{ justifyContent: 'center' }}>
              {loading ? 'Setting password…' : 'Set Password'}
            </button>
          </form>
        )}

        <a href="https://nysterys.com" className="login-back-link" target="_blank" rel="noopener noreferrer">← nysterys.com</a>
      </div>
    </div>
  );
}
